// Hand the message on, and a game's cover as a picture, so n8n can shrink it
// and the lights can take their colours from it.
const { cover, ...body } = $input.first().json.body ?? {};
const item = { json: { body, picture: false } };
if (body.event === 'game_started' && cover) {
  item.json.picture = true;
  item.binary = { cover: { data: cover, mimeType: body.cover_type, fileName: 'cover' } };
}
return [item];

// CabinetOS Game events: the lights in one room follow the game.
// The bridge's address on your network, and the room or zone, named exactly
// as in the Hue app. The rest can stay as it is.
const BRIDGE = "PASTE-THE-BRIDGE-ADDRESS";
const ROOM = "PASTE-THE-ROOM-OR-ZONE";

// The lights' colour while a game runs: "cover" gives each light a colour from
// the game's box art, a colour like "#3050FF" turns them all that colour, and
// "" keeps their own colour.
const PLAYING_COLOUR = "cover";
// A colour of their own for some people, used instead of the one above, by
// their name exactly as the console shows it: { "Sam": "#FF4FA3" }
const PERSON_COLOUR = {};
// A LinkUp game's colour.
const LINKUP = "#A07CF0";
// When every achievement in a game is unlocked: "rainbow" runs the lights
// through every colour, and a colour like "#F2C14E" flashes that colour.
const CELEBRATE = "rainbow";
// How bright the lights are while a game runs and while it is paused, as a
// share of how bright they were before: 1 is as they were, 0 is off.
const PLAYING = 0.2, PAUSED = 0.6;
// Lights that are off when a game starts: "stay off", or "turn on" to light
// them for the game (as a share of full brightness) and turn them off after.
const LIGHTS_OFF = "stay off";
const FADE = 10;  // tenths of a second

// The first time, the bridge gives n8n a key of its own: press the round
// button on the bridge, then start a game within 30 seconds. n8n keeps it.
const saved = $getWorkflowStaticData('global');
if (!saved.key) {
  const answer = await this.helpers.httpRequest({ method: 'POST', url: `http://${BRIDGE}/api`, body: { devicetype: 'cabinetos#n8n' }, json: true });
  saved.key = answer?.[0]?.success?.username;
  if (!saved.key) throw new Error('Press the round button on the Hue bridge, then start a game within 30 seconds');
}
const errors = [];
const hue = async (method, path, body) => {
  const answer = await this.helpers.httpRequest({ method, url: `http://${BRIDGE}/api/${saved.key}${path}`, body, json: true });
  for (const a of [].concat(answer)) if (a && a.error) errors.push(a.error.description);
  return answer;
};
const wait = (ms) => new Promise((done) => setTimeout(done, ms));
// A #RRGGBB colour as Hue's x and y.
const xy = (hex) => {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map((c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));
  const X = 0.4124 * r + 0.3576 * g + 0.1805 * b, Y = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  const all = X + Y + 0.0193 * r + 0.1192 * g + 0.9505 * b || 1;
  return [+(X / all).toFixed(4), +(Y / all).toFixed(4)];
};
// Where a colour sits on the colour wheel, 0 to 6.
const wheel = (r, g, b) => {
  const top = Math.max(r, g, b), spread = top - Math.min(r, g, b);
  return top === r ? ((g - b) / spread + 6) % 6 : top === g ? (b - r) / spread + 2 : (r - g) / spread + 4;
};
// The cover's main colours, most common first, read from the small copy n8n
// made of it. Dark and grey pixels are left out, and so are colours close to
// one already picked, so a cover of greys, black and white gives none. Lamps
// wash colours out, so each one is made vivid.
const coverColours = async () => {
  if (!$input.first().binary?.cover) return [];
  const bmp = await this.helpers.getBinaryDataBuffer(0, 'cover');
  const start = bmp.readUInt32LE(10), width = bmp.readInt32LE(18), height = Math.abs(bmp.readInt32LE(22));
  const step = bmp.readUInt16LE(28) / 8, row = Math.ceil((width * step) / 4) * 4;
  const shades = {};
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const p = start + y * row + x * step;
      const [b, g, r] = [bmp[p], bmp[p + 1], bmp[p + 2]];
      const top = Math.max(r, g, b);
      if (top < 64 || top - Math.min(r, g, b) < top * 0.35) continue;
      const shade = (shades[Math.floor(wheel(r, g, b) * 2)] ??= { n: 0, r: 0, g: 0, b: 0 });
      shade.n++; shade.r += r; shade.g += g; shade.b += b;
    }
  }
  const picked = [];
  for (const s of Object.values(shades).filter((s) => s.n >= 8).sort((a, b) => b.n - a.n)) {
    const [r, g, b] = [s.r, s.g, s.b].map((c) => c / s.n);
    const at = wheel(r, g, b), top = Math.max(r, g, b);
    if (picked.some((p) => Math.min(Math.abs(p.at - at), 6 - Math.abs(p.at - at)) < 0.5)) continue;
    const sat = Math.max((top - Math.min(r, g, b)) / top, 0.8);
    const vivid = [5, 3, 1].map((n) => { const k = (n + at) % 6; return Math.round(255 * (1 - sat * Math.max(0, Math.min(k, 4 - k, 1)))); });
    picked.push({ at, hex: '#' + vivid.map((c) => c.toString(16).padStart(2, '0')).join('') });
  }
  return picked.slice(0, 5).map((p) => p.hex);
};

const m = $input.first().json.body ?? {};
const all = await hue('GET', '');
if (Array.isArray(all)) {
  delete saved.key;
  throw new Error('The Hue bridge no longer knows n8n: press its round button, then start a game within 30 seconds');
}
const room = Object.values(all.groups).find((g) => g.name === ROOM && g.type !== 'Entertainment');
if (!room) throw new Error(`The Hue bridge has no room or zone named "${ROOM}"`);
const now = (id) => all.lights[id].state;
const reachable = room.lights.filter((id) => now(id).reachable !== false);
const lit = reachable.filter((id) => now(id).on);

// What the lights were before the game, kept until it ends, and each light's
// colour while it runs. Lights that were off are in it only with "turn on". A
// start without an end before it keeps the first one, so the lights still go
// back to how they were before any game.
const colour = (st) => st.colormode === 'ct' ? { ct: st.ct } : st.colormode === 'hs' ? { hue: st.hue, sat: st.sat } : { xy: st.xy };
const level = (share) => Object.entries(saved.before ?? {}).map(([id, was]) => ({ id, state: share === 0
  ? { on: false, transitiontime: FADE }
  : { on: true, bri: Math.max(1, Math.round((was.on ? was.bri : 254) * share)), ...(saved.colours?.[id] ? { xy: xy(saved.colours[id]) } : {}), transitiontime: FADE } }));

let set = [];
if (m.event === 'game_started') {
  if (!saved.before) {
    const join = LIGHTS_OFF === 'turn on' ? reachable : lit;
    saved.before = Object.fromEntries(join.map((id) => [id, { on: now(id).on, bri: now(id).bri, ...colour(now(id)), colormode: now(id).colormode }]));
  }
  const linkup = m.linkup_game === 'hosting' || m.linkup_game === 'joined';
  const own = PERSON_COLOUR[m.person] ?? PLAYING_COLOUR;
  const colours = linkup ? [LINKUP] : own === 'cover' ? await coverColours() : own ? [own] : [];
  saved.colours = Object.fromEntries(Object.keys(saved.before).map((id, i) => [id, colours[i % colours.length] ?? null]));
  set = level(PLAYING);
} else if (m.event === 'game_paused') {
  set = level(PAUSED);
} else if (m.event === 'game_resumed') {
  set = level(PLAYING);
} else if (m.event === 'game_ended' && saved.before) {
  // Lights that were off go off again with their own colour, so they come on
  // as before the next time they are turned on.
  set = Object.entries(saved.before).map(([id, was]) =>
    ({ id, state: { on: was.on, bri: was.bri, ...colour(was), transitiontime: FADE } }));
  delete saved.before;
  delete saved.colours;
} else if (m.event === 'achievement_unlocked') {
  set = lit.map((id) => ({ id, state: { alert: 'select' } }));
} else if (m.event === 'set_completed') {
  const party = CELEBRATE === 'rainbow' ? { effect: 'colorloop', sat: 254 } : { xy: xy(CELEBRATE), alert: 'select', transitiontime: 2 };
  for (const id of lit) await hue('PUT', `/lights/${id}/state`, party);
  await wait(CELEBRATE === 'rainbow' ? 10000 : 4000);
  set = lit.map((id) => ({ id, state: { effect: 'none', ...colour(now(id)), transitiontime: FADE } }));
}
for (const { id, state } of set) await hue('PUT', `/lights/${id}/state`, state);

return [{ json: { event: m.event ?? null, room: ROOM, lights: room.lights.length, on: lit.length, changed: set.length, colours: saved.colours ?? null, errors } }];
